INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_056_M4_S5', 'mobility', '5', 'mobility: Movement of individuals or groups between social positions, especially across socioeconomic strata. In Stratification and Inequality, the focus is on the analysis, design, implementation, interpretation, or evaluation of mobility within Sociology, particularly where the Stratification and Inequality module establishes its technical context.', 'SSD_COURSE_056_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M4_S6', 'poverty', '6', 'poverty refers to a condition of insufficient resources or capabilities to achieve socially defined minimum standards of living. In Stratification and Inequality, the focus is on the analysis, design, implementation, interpretation, or evaluation of poverty within Sociology, particularly where the Stratification and Inequality module establishes its technical context.', 'SSD_COURSE_056_M4_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M5_S1', 'primary/secondary groups', '1', 'primary/secondary groups: Groups distinguished by the degree of intimacy, duration, and formality in members'' relationships. In Groups, Organizations and Networks, the focus is on the analysis, design, implementation, interpretation, or evaluation of primary/secondary groups within Sociology, particularly where the Groups, Organizations and Networks module establishes its technical context.', 'SSD_COURSE_056_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M5_S2', 'organizations', '2', 'organizations: Structured social entities with defined or emergent roles, relationships, goals, rules, and patterns of coordination among members. In Groups, Organizations and Networks, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_056_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M5_S3', 'bureaucracy', '3', 'bureaucracy refers to a formal organisational structure based on defined roles, rules, hierarchy, and specialised responsibilities. In Groups, Organizations and Networks, the focus is on the analysis, design, implementation, interpretation, or evaluation of bureaucracy within Sociology, particularly where the Groups, Organizations and Networks module establishes its technical context.', 'SSD_COURSE_056_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M5_S4', 'social networks', '4', 'social networks: Patterns of relationships and ties connecting people, groups, or organisations. In Groups, Organizations and Networks, the focus is on the analysis, design, implementation, interpretation, or evaluation of social networks within Sociology, particularly where the Groups, Organizations and Networks module establishes its technical context.', 'SSD_COURSE_056_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M6_S1', 'demography', '1', 'demography refers to the study of population size, composition, distribution, and change through processes such as fertility, mortality, and migration. In Population, Urbanization and Social Change, the focus is on the analysis, design, implementation, interpretation, or evaluation of demography within Sociology, particularly where the Population, Urbanization and Social Change module establishes its technical context.', 'SSD_COURSE_056_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M6_S2', 'migration', '2', 'migration: Movement of people between geographic locations, considered in relation to its drivers, patterns, consequences, and institutional or socioeconomic context. In Population, Urbanization and Social Change, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_056_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M6_S3', 'urbanization', '3', 'urbanization: Growth of urban populations and the social, spatial, and institutional changes associated with urban development. In Population, Urbanization and Social Change, the focus is on the analysis, design, implementation, interpretation, or evaluation of urbanization within Sociology, particularly where the Population, Urbanization and Social Change module establishes its technical context.', 'SSD_COURSE_056_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M6_S4', 'globalization', '4', 'globalization: Increasing cross-border flows and interdependence of people, goods, capital, information, culture, and institutions. In Population, Urbanization and Social Change, the focus is on the analysis, design, implementation, interpretation, or evaluation of globalization within Sociology, particularly where the Population, Urbanization and Social Change module establishes its technical context.', 'SSD_COURSE_056_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M6_S5', 'social movements', '5', 'social movements: Collective efforts seeking or resisting significant social, political, cultural, or institutional change. In Population, Urbanization and Social Change, the focus is on the analysis, design, implementation, interpretation, or evaluation of social movements within Sociology, particularly where the Population, Urbanization and Social Change module establishes its technical context.', 'SSD_COURSE_056_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M7_S1', 'digital society', '1', 'digital society: Social life shaped by digital technologies, platforms, networks, data, and digitally mediated interaction. In Contemporary Sociological Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of digital society within Sociology, particularly where the Contemporary Sociological Analysis module establishes its technical context.', 'SSD_COURSE_056_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M7_S2', 'institutions and technology', '2', 'institutions and technology refers to the interaction between technological systems and the social institutions, rules, roles, and practices that shape their use. In Contemporary Sociological Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of institutions and technology within Sociology, particularly where the Contemporary Sociological Analysis module establishes its technical context.', 'SSD_COURSE_056_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M7_S3', 'comparative analysis', '3', 'comparative analysis: Systematic comparison of social phenomena across groups, settings, periods, or cases to identify similarities, differences, and explanatory patterns. In Contemporary Sociological Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of comparative analysis within Sociology, particularly where the Contemporary Sociological Analysis module establishes its technical context.', 'SSD_COURSE_056_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_056_M7_S4', 'mixed-method sociology', '4', 'mixed-method sociology: Sociological research combining qualitative and quantitative methods to study a question using complementary forms of evidence. In Contemporary Sociological Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of mixed-method sociology within Sociology, particularly where the Contemporary Sociological Analysis module establishes its technical context.', 'SSD_COURSE_056_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M1_S1', 'schemas', '1', 'schemas: Organised mental structures that help people interpret, remember, and predict information about social objects and situations. In Social Cognition, the focus is on the analysis, design, implementation, interpretation, or evaluation of schemas within Social Psychology, particularly where the Social Cognition module establishes its technical context.', 'SSD_COURSE_057_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M1_S2', 'attribution', '2', 'attribution refers to the process of explaining the causes of people''s behaviour or events using internal or external factors. In Social Cognition, the focus is on the analysis, design, implementation, interpretation, or evaluation of attribution within Social Psychology, particularly where the Social Cognition module establishes its technical context.', 'SSD_COURSE_057_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M1_S3', 'heuristics', '3', 'heuristics: Mental shortcuts used to make social judgments quickly, often with possible systematic biases. In Social Cognition, the focus is on the analysis, design, implementation, interpretation, or evaluation of heuristics within Social Psychology, particularly where the Social Cognition module establishes its technical context.', 'SSD_COURSE_057_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M1_S4', 'social perception', '4', 'social perception: Processes through which people form impressions and interpret other people''s characteristics, intentions, and behaviour. In Social Cognition, the focus is on the analysis, design, implementation, interpretation, or evaluation of social perception within Social Psychology, particularly where the Social Cognition module establishes its technical context.', 'SSD_COURSE_057_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M1_S5', 'judgment', '5', 'judgment: Evaluation or decision-making about people, groups, or social situations using available information and cognitive processes. In Social Cognition, the focus is on the analysis, design, implementation, interpretation, or evaluation of judgment within Social Psychology, particularly where the Social Cognition module establishes its technical context.', 'SSD_COURSE_057_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M2_S1', 'attitude formation', '1', 'attitude formation refers to the development of evaluations or preferences toward people, objects, issues, or behaviours. In Attitudes and Persuasion, the focus is on the analysis, design, implementation, interpretation, or evaluation of attitude formation within Social Psychology, particularly where the Attitudes and Persuasion module establishes its technical context.', 'SSD_COURSE_057_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M2_S2', 'cognitive dissonance', '2', 'cognitive dissonance: Psychological discomfort arising from inconsistency between cognitions, attitudes, or behaviour that can motivate change. In Attitudes and Persuasion, the focus is on the analysis, design, implementation, interpretation, or evaluation of cognitive dissonance within Social Psychology, particularly where the Attitudes and Persuasion module establishes its technical context.', 'SSD_COURSE_057_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M2_S3', 'persuasion models', '3', 'persuasion models: Models explaining how messages, sources, recipients, and contexts influence changes in attitudes or behaviour. In Attitudes and Persuasion, the focus is on the analysis, design, implementation, interpretation, or evaluation of persuasion models within Social Psychology, particularly where the Attitudes and Persuasion module establishes its technical context.', 'SSD_COURSE_057_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M2_S4', 'resistance', '4', 'resistance: Processes that reduce or oppose attempts to change a person''s attitudes, beliefs, or behaviour. In Attitudes and Persuasion, the focus is on the analysis, design, implementation, interpretation, or evaluation of resistance within Social Psychology, particularly where the Attitudes and Persuasion module establishes its technical context.', 'SSD_COURSE_057_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M3_S1', 'attraction', '1', 'attraction refers to the processes and factors influencing positive interpersonal evaluation and desire for social contact. In Interpersonal Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of attraction within Social Psychology, particularly where the Interpersonal Processes module establishes its technical context.', 'SSD_COURSE_057_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M3_S2', 'relationships', '2', 'relationships: Patterns of interaction, attachment, exchange, support, and conflict between people. In Interpersonal Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of relationships within Social Psychology, particularly where the Interpersonal Processes module establishes its technical context.', 'SSD_COURSE_057_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M3_S3', 'prosocial behaviour', '3', 'prosocial behaviour: Behaviour intended to benefit, help, support, or protect another person or group. In Interpersonal Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of prosocial behaviour within Social Psychology, particularly where the Interpersonal Processes module establishes its technical context.', 'SSD_COURSE_057_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M3_S4', 'aggression', '4', 'aggression: Behaviour intended to harm another person or group, including its social and psychological determinants. In Interpersonal Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of aggression within Social Psychology, particularly where the Interpersonal Processes module establishes its technical context.', 'SSD_COURSE_057_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M3_S5', 'conflict', '5', 'conflict: Incompatible goals, interests, beliefs, or actions between individuals or groups and the processes through which conflict develops. In Interpersonal Processes, the focus is on the analysis, design, implementation, interpretation, or evaluation of conflict within Social Psychology, particularly where the Interpersonal Processes module establishes its technical context.', 'SSD_COURSE_057_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M4_S1', 'group norms', '1', 'group norms: Shared expectations within a group about appropriate attitudes, behaviour, and interaction. In Groups and Collective Behaviour, the focus is on the analysis, design, implementation, interpretation, or evaluation of group norms within Social Psychology, particularly where the Groups and Collective Behaviour module establishes its technical context.', 'SSD_COURSE_057_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M4_S2', 'conformity', '2', 'conformity: Adjustment of attitudes, judgments, or behaviour toward perceived group norms or expectations. In Groups and Collective Behaviour, the focus is on the analysis, design, implementation, interpretation, or evaluation of conformity within Social Psychology, particularly where the Groups and Collective Behaviour module establishes its technical context.', 'SSD_COURSE_057_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M4_S3', 'obedience', '3', 'obedience: Behavioural compliance with a directive from an authority figure or recognised authority. In Groups and Collective Behaviour, the focus is on the analysis, design, implementation, interpretation, or evaluation of obedience within Social Psychology, particularly where the Groups and Collective Behaviour module establishes its technical context.', 'SSD_COURSE_057_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M4_S4', 'group decision-making', '4', 'group decision-making: Processes through which group members combine information, preferences, and judgments to reach collective decisions. In Groups and Collective Behaviour, the focus is on the analysis, design, implementation, interpretation, or evaluation of group decision-making within Social Psychology, particularly where the Groups and Collective Behaviour module establishes its technical context.', 'SSD_COURSE_057_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M4_S5', 'collective action', '5', 'collective action: Coordinated behaviour by multiple people pursuing a shared social or political objective. In Groups and Collective Behaviour, the focus is on the analysis, design, implementation, interpretation, or evaluation of collective action within Social Psychology, particularly where the Groups and Collective Behaviour module establishes its technical context.', 'SSD_COURSE_057_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M5_S1', 'social identity', '1', 'social identity: Part of a person''s self-concept derived from perceived membership in social groups. In Identity and Intergroup Relations, the focus is on the analysis, design, implementation, interpretation, or evaluation of social identity within Social Psychology, particularly where the Identity and Intergroup Relations module establishes its technical context.', 'SSD_COURSE_057_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M5_S2', 'categorization', '2', 'categorization: Grouping people or social information into categories that simplify perception and judgment. In Identity and Intergroup Relations, the focus is on the analysis, design, implementation, interpretation, or evaluation of categorization within Social Psychology, particularly where the Identity and Intergroup Relations module establishes its technical context.', 'SSD_COURSE_057_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M5_S3', 'prejudice', '3', 'prejudice refers to an evaluative attitude toward a person or group based partly on group membership rather than individual information. In Identity and Intergroup Relations, the focus is on the analysis, design, implementation, interpretation, or evaluation of prejudice within Social Psychology, particularly where the Identity and Intergroup Relations module establishes its technical context.', 'SSD_COURSE_057_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M5_S4', 'stereotyping', '4', 'stereotyping: Attributing generalised beliefs or characteristics to members of a social group. In Identity and Intergroup Relations, the focus is on the analysis, design, implementation, interpretation, or evaluation of stereotyping within Social Psychology, particularly where the Identity and Intergroup Relations module establishes its technical context.', 'SSD_COURSE_057_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M5_S5', 'intergroup conflict', '5', 'intergroup conflict: Conflict arising between social groups over goals, resources, status, identity, or perceived threats. In Identity and Intergroup Relations, the focus is on the analysis, design, implementation, interpretation, or evaluation of intergroup conflict within Social Psychology, particularly where the Identity and Intergroup Relations module establishes its technical context.', 'SSD_COURSE_057_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M6_S1', 'normative influence', '1', 'normative influence: Pressure to conform because of a desire for social acceptance or avoidance of rejection. In Social Influence and Communication, the focus is on the analysis, design, implementation, interpretation, or evaluation of normative influence within Social Psychology, particularly where the Social Influence and Communication module establishes its technical context.', 'SSD_COURSE_057_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M6_S2', 'informational influence', '2', 'informational influence: Influence arising when people use others'' judgments as evidence about uncertain or ambiguous situations. In Social Influence and Communication, the focus is on the analysis, design, implementation, interpretation, or evaluation of informational influence within Social Psychology, particularly where the Social Influence and Communication module establishes its technical context.', 'SSD_COURSE_057_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M6_S3', 'communication', '3', 'communication: Exchange and interpretation of information between people through verbal, non-verbal, and mediated channels. In Social Influence and Communication, the focus is on the analysis, design, implementation, interpretation, or evaluation of communication within Social Psychology, particularly where the Social Influence and Communication module establishes its technical context.', 'SSD_COURSE_057_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M6_S4', 'misinformation', '4', 'misinformation: False or inaccurate information shared or believed without necessarily intending to deceive. In Social Influence and Communication, the focus is on the analysis, design, implementation, interpretation, or evaluation of misinformation within Social Psychology, particularly where the Social Influence and Communication module establishes its technical context.', 'SSD_COURSE_057_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M7_S1', 'health', '1', 'health refers to a multidimensional condition of physical, mental, or social well-being considered in relation to individual, social, economic, and environmental determinants. In Applications of Social Psychology, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_057_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M7_S2', 'organizations', '2', 'organizations: Structured social entities with defined or emergent roles, relationships, goals, rules, and patterns of coordination among members. In Applications of Social Psychology, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_057_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M7_S3', 'education', '3', 'education: Structured processes and institutions through which knowledge, skills, values, and capabilities are developed and transmitted across individuals and society. In Applications of Social Psychology, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_057_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M7_S4', 'environmental behaviour', '4', 'environmental behaviour: Actions affecting the natural or built environment and the social and psychological factors influencing those actions. In Applications of Social Psychology, the focus is on the analysis, design, implementation, interpretation, or evaluation of environmental behaviour within Social Psychology, particularly where the Applications of Social Psychology module establishes its technical context.', 'SSD_COURSE_057_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_057_M7_S5', 'interventions', '5', 'interventions: Planned activities designed to change specified psychological processes, social behaviour, or group outcomes. In Applications of Social Psychology, the focus is on the analysis, design, implementation, interpretation, or evaluation of interventions within Social Psychology, particularly where the Applications of Social Psychology module establishes its technical context.', 'SSD_COURSE_057_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M1_S1', 'growth models', '1', 'growth models: Economic models explaining long-run changes in output, productivity, capital, labour, and technological progress. In Growth and Structural Transformation, the focus is on the analysis, design, implementation, interpretation, or evaluation of growth models within Development Economics, particularly where the Growth and Structural Transformation module establishes its technical context.', 'SSD_COURSE_058_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_058_M1_S2', 'productivity', '2', 'productivity: Output produced per unit of an input such as labour or capital. In Growth and Structural Transformation, the focus is on the analysis, design, implementation, interpretation, or evaluation of productivity within Development Economics, particularly where the Growth and Structural Transformation module establishes its technical context.', 'SSD_COURSE_058_M1_S2', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;